use cohdl::{ast::ItemKind, diag::Diagnostics, lex, parse, span::SourceMap};
use std::io::{self, BufRead};

fn main() {
    for path in io::stdin().lock().lines() {
        let path = path.unwrap();
        let source = std::fs::read_to_string(&path).unwrap();
        if std::env::args().nth(1).as_deref() == Some("--check") {
            let checked = cohdl::pipeline::check_files_in_with_deps(
                "probe", &[], &[(path.clone(), source)], None).unwrap();
            let passed = !checked.diags.has_errors() && checked.selection_error.is_none();
            println!("C\t{}\t{}\t{}\t{}", path, passed,
                checked.ir.as_ref().map_or(0, |ir| ir.instances.len()),
                checked.ir.as_ref().map_or(0, |ir| ir.nets.len()));
            for d in checked.diags.iter() {
                println!("E\t{}\t{}\t{}\t{}\t{}", path, d.code, d.primary.span.start,
                    d.primary.span.end, d.message.replace('\t', "\\t").replace('\n', "\\n"));
            }
            continue;
        }
        let mut sm = SourceMap::new();
        let file = sm.add_file(path.clone(), source.clone());
        let mut diags = Diagnostics::new();
        let tokens = lex::lex(file, &source, &mut diags);
        let ast = parse::parse(tokens, &mut diags);
        println!("F\t{}\t{}", path, diags.error_count());
        for item in ast.items {
            let decl = match &item.kind {
                ItemKind::Fn(f) => Some(("fn", &f.name.name, f.generics.len())),
                ItemKind::Subdesign(s) => Some(("subdesign", &s.name.name, s.generics.len())),
                _ => None,
            };
            if let Some((kind, name, generics)) = decl {
                println!("D\t{}\t{}\t{}\t{}\t{}\t{}\t{}", path, kind, name,
                    item.decl_span.start, item.decl_span.end, generics, item.is_pub);
            }
        }
        for d in diags.iter() {
            println!("E\t{}\t{}\t{}\t{}\t{}", path, d.code, d.primary.span.start,
                d.primary.span.end, d.message.replace('\t', "\\t").replace('\n', "\\n"));
        }
    }
}

